1:감동받는 단어나 구절 찾기(영적터치)

1. 1분기도

2. 본문성경 읽기(3번)

3. 반복단어 찾기(형광펜 추천)

- 아내(22,23,24,25,28,31,33절)

- 남편(22,23,24,25,28,33절)

- 복종(21,22,24절)

- 그리스도(23,24,25,29,32절)

