5.하나님 찾기(관찰)

6.인간 찾기(관찰)

- 어둠의 일에 참여하지 말고 책망하라

- 지혜 있는 자 같이 하여 세월을 아껴라 때가 악하다

- 주의 뜻이 무엇인가 이해하라

