- 위의 것을 생각하고 땅의 것을 생각하지 말라

- 땅에 있는 지체를 죽이라

- 새 사람을 입었으니 이는 하나님의 형상을 따라 지식에까지 새롭게 하심을 입은 자니라

7.하나님 찾기(해석)

8.인간 찾기(해석)

- 그리스도와 함께 살리심을 받은 자들을 위의 것을 생각하기 위해서는

- 기본적으로 말씀과 기도의 삶을 살아야하고, 

- 나아가 무슨 일을 하든지 성령 안에서 생각하고 행해야 한다.

- 떄떄로 주님을 만나기 전에 행했던 일들이 떠오르거나 유혹이 있을 수 있다. 그러나 신자는 이런 것들을 멀리해야한다.

- 그렇지 않으면 내주하셨던 성령님은 소멸하게 되고, 예전의 삶으로 돌아가게 된다.

- 말씀과 기도의 삶이 끊어지면 땅의 것에 사로잡히게 되어있다.

- 그러므로 말씀과 기도의 삶을 놓아서는 안 된다.

- 새 사람은 창조된 형상을 갖고 살며 하나님을 더욱 닮아가게 된다.

- 말씀과 기도로 성령님과 친밀해지고 성령님의 생각이 나의 생각이 되어 마음도 태도도 언행도 변하게 된다.

- 10절 말씀대로 지식에까지 새롭게 하심을 입게 된다.

- 이것은 완전히 다른 사람이 되는 것이다.

- 이전의 나는 죽고, 그리스도로 말미암아 새로 태어나는 것이다.  

- 신자는 지식에까지 새롭게 하심을 입는 새 사람의 삶을 추구해야 한다.

- 이를 위해 말씀을 읽고 기도하는 삶을 지속해야 한다.

9.적용(나) 

- 지식에까지 새롭게 되기 위해 오늘도 말씀과 기도를 멈추지 말아야겠다

