8.인간 찾기(해석)

- 신자는 하나님의 나라와 영광을 바라보며 하나님께 합당하게 행해야 한다.

- 이 거룩한 행동은 자신을 지키는 것이며, 나아가 주변 사람들에게 교회란 어떤 것인가 보여주는 것이다. 

- 신자를 통해 주변 불신자들이 예수님을 바라보게 되고 생각하게 된다.

- 데살로니가교회 형제들은 바울의 말을 하나님의 말씀으로 받았고, 이러한 태도는 이들이 얼마나 말씀을 사모하고 귀히 여기는 지 알 수 있는 부분이다.

- 신자는 말씀을 사람의 지혜있는 말이 아니라, 살아계신 하나님의 말씀으로 믿고 받아야 한다.

- 그래야 믿음 가운데 삶에서 능력이 나타난다. 하나님의 말씀은 사실이고, 살아있고 활력이 있다.

- 동족에게서 받는 고난은 괴롭지만, 예수님과 믿음의 선진들도 동일하거나 더 심한 고난을 받았다는 것을 기억해야 한다.

- 세상에서의 고난은 금방 지나가지만, 예수님과 함께 기쁨과 영광을 누리는 시간은 영원하다.

- 형제들의 믿음과 성장이 바울에게는 기쁨이요 자랑거리였다.

- 세상의 그 무엇이 아니라, 형제들의 믿음과 성장이 기쁨과 자랑거리라는 것은 바울 일행의 기준이 하늘에 있다는 것을 확실히 보여준다.

- 신자는 위의 것을 구할 때 순전한 기쁨을 누릴 수 있다.

