8. 인간(해석):

- 사도 바울은 편지를 통해 디모데에게 교회는 살아 계신 하나님의 집이며, 진리의 기둥과 터라고 말한다. 이 말씀은 단순히 교회에 대한 설명이 아니라, 사역의 어려움 속에 있던 디모데에게 주는 깊은 위로였을 것이다.

- 당시 디모데는 거짓 교훈과 싸워야 했고, 교회를 바르게 세워야 했으며, 수많은 사람들의 시선과 비판을 감당해야 했다. 그런 디모데에게 바울은 예수님을 언급했다. 육신으로 나타나시고, 의롭다 하심을 받으시고, 만국 가운데 전파되시고, 영광 가운데 올려지신 예수님을 떠오르게 함으로써 디모데의 시선을 다시 복음의 본질로 향하게 한다.

- 우리는 종종 신앙 공동체 안에서 어려움을 겪을 때가 있다. 함께 믿음을 나누는 사람들 사이에서도 상처를 받을 수 있고, 오해와 갈등을 경험할 수도 있다. 이러한 일은 교회뿐만 아니라 가정에서도 동일하게 일어난다. 가장 가까운 관계일수록 기대가 크기 때문에 상처도 더 크게 다가올 때가 있다.

- 그렇다면 우리는 이러한 위기의 순간에 무엇을 바라보아야 할까. 무엇으로 이 어려움을 극복해야 할까. 그 답은 오직 예수 그리스도이시다.

- 죄가 없으신 예수님께서는 이 땅에 오셔서 우리의 죄를 대신 짊어지시고 십자가를 지셨다. 거절당하시고, 조롱받으시고, 배신당하셨음에도 끝까지 사랑하셨다. 예수님의 십자가는 단순히 우리를 구원한 사건이 아니라, 우리가 어떻게 살아가야 하는지를 보여주는 가장 위대한 사랑의 본보기이다.

- 우리는 그 사랑으로 인해 구원받은 존재이다. 그리고 그 사랑으로 인해 오늘도 살아갈 힘을 얻는다. 우리는 사람을 바라보기보다 예수님을 바라보아야 한다. 상처를 준 사람보다 나를 위해 십자가를 지신 주님을 기억해야 한다. 그때 비로소 우리는 무너지지 않고 다시 일어설 수 있다. 

- 참 어려운 일이지만 반드시 해내야 할 일이다.

9. 적용(나): 

- 어려운 상황에서 포기하기 보다 예수님을 바라볼 수 있는 믿음이 주어지길 기도해야겠다.

