참 과부는 선한 일을 하기 

7. 하나님 찾기(해석)

8.인간 찾기(해석)

바울은 디모데전서 5장에서 당시 사회적 약자였던 참과부를 신자들이 어떻게 대해야 하는지 가르치고 있다. 

또한 참과부의 입장에서도 어떤 자세와 삶의 태도를 가져야 하는지 구체적으로 알려준다.

먼저 신자들에게는 참과부를 존대하며, 자녀와 손자들이 홀로 계신 부모에게 효를 다할 것을 권면한다. 

부모를 돌보는 것은 하나님 앞에서 아름답고 마땅한 일임을 강조한다. 

반면 참과부에게는 사람만 바라보지 말고 하나님께 소망을 두며, 주야로 간구와 기도에 힘쓸 것을 가르친다.

생각해 보면 사회에서 소외되기 쉽고 외로움에 놓일 수 있는 사람이라도 공동체가 서로 관심을 가지고 사랑으로 돌본다면 얼마나 따뜻하고 행복한 공동체가 되겠는가? 

우리 남북청년연합선교회(남청연) 안에도 혹시 외롭거나 힘든 시간을 보내는 지체가 있다면 더욱 관심을 갖고 사랑으로 섬기기를 기도한다.

나 역시 홀아비로 살아가며 때때로 외로움을 느낄 때가 있다. 

그러나 외로운 마음이 나를 지배하도록 내버려 두지 않고, 하나님께 소망을 두며 기도와 말씀 가운데 주님과 깊이 교제하기를 원한다. 

사람의 위로도 귀하지만, 가장 큰 위로와 소망은 하나님께로부터 온다는 사실을 다시 한번 마음에 새긴다.

9. 적용 (구체적으로) 

오늘도 오늘의 말씀 붙잡고 간절히 기도하는 시간을 가져야겠다.

