- 상전을 존경하고 잘 섬기도록 가르치라

- 거짓 교훈을 말하고 말씀을 따르지 않는 자들을 경계하라

- 자족하는 마음이 있으면 경건은 큰 유익이 된다

- 부하려 하는 자는 결국 멸망하고 최후와 돈을 사랑하는 마음은 자신에게 해롭다 

  

7.하나님 찾기(해석)

8.인간 찾기(해석)

- 로마 시대는 계급 사회로서 노예는 상전을 잘 섬겨야 했다. 형제들 중에도 노예나 하급 계층이 있었으므로 이 말씀은 시대적으로 파격적인 말씀이다.

- 교회에서는 모든 인간이 평등하기에 노예도 형제로서 공동체 생활을 했다는 것을 알 수 있다.

- 하지만, 사회에서는 하급 계층이므로 상전을 잘 섬겨야 했다. 

- 이들이 상전을 잘 모시지 않으면 비방을 받는 것은 이들뿐만 아니라 하나님과 교회이므로 하급 계층의 형제들이 상전을 존경하도록 가르치게 한 것이다.

- 또한 교회 형제 중에 상전과 노예가 함께 공동 생활을 하면서 형제애를 누리게 되면, 교회 내에서는 사회에서이 계층이 무너지게 되는데 이로 인해 사회에서 상전을 가볍게 여기게 될 수 있기에, 더욱 잘 섬길 것을 요구한다.

- 상전과 사이가 가깝거나 상전이 선하면, 아무래도 가볍게 여기게 되는 것이 사람의 마음이다.

- 이단이 거짓 교훈을 말하는 경우가 있고, 이런 경우 교회내에 다툼이 일어나게 된다.

- 교회에서 다툼이 일어나는 데에는 권력과 물질 등 자신의 유익이 이유가 된다.

- 지도자는 이단과 그 교훈을 경계하고 교회를 잘 다스려야 한다.

- 자족하는 마음이 있으면 경건이 큰 유익이 된다.

- 자족은 위 말씀처럼 먹고 입을 것이 있는 것으로 만족하는 것인데, 이것은 믿는 자만이 온전히 누릴 수 있는 경지(?)로서,

- 하나님 한 분만으로 만족할 수 있는 자들에게 주어지는 능력이다.

- 인생의 기쁨이 하나님께로부터 주어짐을 알고 누리고 있는 이들만 하나님 한 분만으로 만족할 수 있다. Soio dios basta.     

- 부하려 하거나 돈을 사랑하면 인간은 무너지게 되어 있다.

- 과한 욕심이 생겨 문제가 발생하거나 미혹을 받아 믿음에서 떠나기도 하고 많은 근심으로 자신을 찌르는 결과가 발생하기도 한다.

- 돈은 삶을 사는데 필요한 것이지 사랑의 대상이 아니다.

- 특히 신자는 돈을 하나님 나라 확장에 섬김에 어떻게 사용할지 기도하고 생각해야지 이것으로 부귀영화를 누리려고 해서는 안되는 것이다.

- 부자가 되려는 것과 돈을 많이 벌고자 하는 마음의 근원이 하나님 나라 확장과 섬김이라면 모르겠지만, 허나 그럴지라도 부자가 아니고 돈이 많이 없어도 우리는 하나님 나라 확장과 섬기는 일을 할 수 있다는 것을 명심해야 한다.

- 그렇다고 돈을 미워하라는 것은 아니다. 돈은 물질세계에서 살아가기 위해 꼭 필요한 것이다. 먹고 입고 자고 생활하는데 과하지도 부족하지도 않길 바란다.

- 부디 하나님이 원하시는 주 안에서 모두가 잘 먹고 잘 사는 그런 교회들이 많이 생겨나길 바란다. 

