4.주제 만들기: 인정받는 일꾼으로 하나님께 드리라

5.하나님 찾기(관찰)

- 주는 미쁘시니 자기를 부인할 수 없으시다

6.인간 찾기(관찰)

- 이 일을 기억하여 말다툼을 하지 말라고 하나님 앞에서 엄히 명하라

- 진리의 말씀을 옳게 분별하라

- 부끄러울 것이 없는 일꾼으로 인정된 자로 자신을 하나님 앞에 드리기를 힘쓰라

- 부활이 이미 지나갔다 함으로 어떤 사람들의 믿음을 무너뜨리는 자들이 있다

- 큰 집에는 금 그릇과 은 그릇뿐 아니라 나무 그릇과 질그릇도 있어 귀하게 쓰는 것도 있고 천하게 쓰는 것도 있다

7.하나님 찾기(해석)

- 주는 미쁘시기에 신자를 구원하시고 영광의 자리에 함께하게 하신다는 주의 말씀은 진리이다.

- 예수님과 함께 부활하고 통치한다는 주의 말씀은 반드시 이루어진다는 것이다.

8.인간 찾기(해석)

- 이 일을 기억해야 말다툼을 하지 않을 것이다. 신자는 주의 말씀을 기억해야 한다.

- 기억하려면 말씀을 묵상해야 한다. 그리고 암송해야 한다.

- 신자의 부활과 통치는 참이다. 

- 목회자(또는 목자)는 진리의 말씀을 옳게 분별해야 한다. 신자 또한 잘 배워 진리의 말씀을 옳게 분별할 수 있어야 한다.

- 목회자가 진리의 말씀을 옳게 분별하고 확신이 있어야 형제들을 다툼없이 잘 이끌 수 있다.

- 이단은 언제나 교회를 노리고 있다.

- 목회자는 부끄러울 것이 없어야 한다. 교회 안팎에서 잡음이 없는 목회자가 되도록 목숨을 걸고 자신을 지켜야 한다. 죄와는 피 흘리기까지 싸워야 할 것이다.

- 이런 목회자가 있다면 공동체의 신자들 또한 목회자와 함께 죄와 피 흘리기까지 싸울 것이다. 

- 위 말씀과 더불어 목회자는 일을 열심히 하는 자로서 하나님 앞에 서야 한다.

- 이를 위해 힘써야 한다.

- 목자는 성실한 사람이어야 한다. 

- 부활이 없다, 성령은 없다, 또는 예수는 없다 라는 이단들이 있고,

- 이들은 교회에 침투한다.

- 신자는 이것을 정확히 기억해야 한다.

- 부활과 통치는 명약관화한 것이기에 다툴 필요도 없다.

- 이단을 물리치고 진리만 따르면 된다.

 

- 집에서 사용하는 그릇이 다양한 만큼 공동체에도 사회적 신분적으로 다양한 사람이 있다.

- 하나님 앞에서는 신분의 고하 또는 능력의 고하가 중요한 것이 아니라, 얼마나 하나님을 의지하고 사랑하는 사람인가, 그래서 얼마나 세상과 구별된 삶을 살고 있는가 이것이 중요할 것이다. 

9.적용(나) 

- 예수님을 사랑하여 늘 주님을 묵상하고, 맡겨진 일을 성실하게 하는 신자가 돼야겠다. 

10.영적 터치(단어/구절)

11.믿음과 회개 및 감사기도로 마무리

12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);
