- 이들 중에 남의 집에 가만히 들어가 어리석은 사람을 유인하는 자가 있고

- 이들로 인해 어리석은 사람은 끝내 진리의 지식에 이를 수 없다고 말한다 

- 이들은 진리를 대적하는 자들인데 그 마음이 부패하고 믿음에 관하여는 버림받은 자들이다

7.하나님 찾기(해석)

8.인간 찾기(해석)

- 말세는 예수님의 초림부터 재림 때까지 기간을 뜻하는 것으로 현재도 말세에 해당한다.

- 고통의 때가 이른다고 했는데 그 고통의 때는 이미 왔다. 

- 여기서 말하는 고통의 때는 문맥상 경건하지 못한 자들로 인한 고통을 말하는 것으로 보인다.

- 하나님 보다 자신을 사랑하여 쾌락을 쫓고 도덕적 타락에 이르는 사람들로 인해 교회가 고통을 겪는 것이다.

- 이 고통의 때는 교회 공동체 외부의 고통이 아니라, 교회 공통체 내의 문제로 이천 년 전부터 와 있었고, 오늘 날 교회들을 보면 더욱 극심해진 것으로 보인다.

- 경건의 모양이 있으나 경건의 능력이 없다는 것은 교회 공동체에 함께 하는 사람으로서 겉모습은 경건하지만, 쾌락을 좇거나 도덕적으로 타락한 자들을 뜻한다.

- 겉모습이 경건하다는 것이 행실이 경건하다는 것은 아니며, 종교의식에 함께 참여하고 있는 모습을 뜻한다.

- 신자들은 이들을 경계해야 한다. 믿음의 사람이니 용납하고 함께 해야지 라고 생각하면 안된다.

- 성경에서는 그들을 떠나라고 명령한다.

- 그들은 모세 시대에 바로 왕의 마술사들(얀네와 얌브레)처럼 결국에는 패하게 되어 있으며, 마음이 부패하고 믿음에 관하여는 버림받은 자들이다.

- 그들은 남의 집에 조용히 침투하여 그들을 잘못된 지식으로 유인한다. 어리석은 사람은 미혹되어 진리에 이르지 못하게 된다.

- 이단은 항상 신자들을 노리고 있다. 이천 년 전에도 지금도 그렇다.

- 어리석은 자가 되지 않도록 말씀과 기도에 깨어 있어야 한다. 

