2026년 06월 20일 

디모데후서 4장 1절-10절

1.1분기도

2. 본문 읽기(3번)

3. 반복 단어 및 같은 의미 찾기:

전도자의 일/직무: 5절

심판하실/재판장: 1절 8절

나를 버리고/갔고: 10절

떠날 시각/달려갈 길을 마치고: 6절 7절

심판하실 그리스도 예수/의로우신 재판장: 1절 8절

4. 주제:

전도자가 받을 의의 면류관 

5. 하나님 찾기(관찰)

심판자 되신 그리스도 예수

의로우신 재판장 예수

6. 인간 찾기(관찰)

끝까지 믿음을 지킨 바울

바울을 버리고 떠난 데마

7. 하나님 찾기(해석)

8.인간 찾기(해석)

바울은 육체적으로는 외롭고 힘든 상태에 있었던 것으로 보인다. 특히 10절에서 바울은 "데마는 이 세상을 사랑하여 나를 버리고"라고 기록함으로써 자신의 안타까운 현실을 솔직하게 드러낸다. 

그러나 그의 영적인 상태는 전혀 달랐다. 바울은 끝까지 천국의 소망과 기쁨으로 가득 차 있었다.

8절의 "의의 면류관이 예비되었으므로"라는 말씀을 보면, 바울은 단순히 구원받는 것에 만족한 사람이 아니었음을 알 수 있다. 

그는 생의 마지막 순간까지 하나님께서 주실 상급을 바라보며 믿음의 경주를 멈추지 않았다. 

노년에 이르러서도 선한 싸움을 싸우고, 달려갈 길을 마치며, 믿음을 지켰다고 고백할 수 있었던 것은 참으로 놀라운 은혜이다.

바울이 이처럼 열악한 환경 속에서도 끝까지 사명을 감당할 수 있었던 이유는 주님께서 맡기신 사명 때문이었을 것이다. 

2절의 "너는 말씀을 전파하라. 때를 얻든지 못 얻든지 항상 힘쓰라"는 말씀처럼, 그는 복음 전파에 대한 뜨거운 열정과 사명감을 가지고 살았다. 그의 삶 전체는 예수 그리스도의 복음을 전하는 데 드려진 삶이었다.

또한 바울은 복음을 전하는 일뿐만 아니라 성도들을 섬기고 나누는 삶에도 힘썼다. 그의 삶은 복음과 사랑이 함께 흘러가는 삶이었다.

이 말씀을 묵상하면서 나 역시 한강의 대교 복음을 전하는 사명을 더욱 붙들어야겠다는 마음이 든다. 남북청년연합선교회와 더불어 하나님께서 맡기신 전도의 사명을 충성스럽게 감당하기를 소망한다. 

비록 때로는 외롭고 어려운 순간이 있을지라도, 훗날 주님께서 예비하신 의의 면류관을 생각하면 기쁨과 감사가 넘친다.

오늘도 바울처럼 끝까지 믿음을 지키며, 주님 오시는 날까지 복음 전파의 사명을 충성스럽게 감당하는 삶이 되기를 기도한다.

9. 적용 (구체적으로) 

마포대교 한강대교 외에 많은 한강의 위치한 대교를 우리 남청연 전도지가 되도록 주님께 요청 기도를 올려야겠다.

