- 오늘 말씀을 통해 하나님의 깊은 사랑을 다시 묵상하게 된다. 하나님께서는 굳이 하지 않으셔도 될 일을 하셨다. 죄로 하나님을 떠난 인간을 외면하셔도 되었지만, 하나님은 우리를 너무나 사랑하셨기에 친히 인간의 몸을 입고 이 땅에 오셨다. 그리고 우리의 죄를 대신하여 십자가를 지셨다. 왜 이토록 우리를 사랑하시는지, 그 크고 깊은 마음은 아무리 묵상해도 다 헤아릴 수 없다.

- 신앙생활을 오래 할수록 오히려 이 사건은 더욱 놀랍게 다가온다. 나이가 들어갈수록 누군가를 위해 희생하고, 손해를 감수하며, 조건 없이 사랑하는 일이 얼마나 어려운지 조금씩 알게 되기 때문이다. 그렇기에 하나님의 사랑은 인간의 기준으로는 도저히 이해할 수 없는 사랑임을 더욱 깨닫게 된다.

- 만일 하나님의 조건 없는 사랑이 없었다면, 다른 사람을 위해 희생하고 봉사하며 살아가는 삶은 큰 의미를 찾기 어려웠을 것이다. 그러나 하나님께서 먼저 우리를 사랑하셨기에 우리도 사랑할 수 있는 존재가 되었다. 사랑은 인간에게서 시작되는 것이 아니라, 하나님으로부터 흘러오는 은혜임을 다시 고백하게 된다.

