아니하나니/아니한 것이라: 7절 8절

4. 주제:

육체의 예법

5. 하나님 찾기(관찰)

6. 인간 찾기(관찰)

첫 장막에 들어가 섬기는 예식을 행하는 제사장들

둘째 장막(지성소)에 홀로 일 년에 한 번 들어가는 대제사장 

7. 하나님 찾기(해석)

히브리서 저자는 구약 시대의 성막과 지성소의 용도를 설명하며, 제사장과 대제사장의 역할을 기록하고 있다. 

그들은 하나님께 드리는 제사와 예식을 통해 자신과 백성의 죄를 속하는 사역을 감당했다. 

그러나 9절은 이러한 제사의 한계를 분명히 보여 준다. "드리는 예물과 제사는 섬기는 자를 그 양심상 온전하게 할 수 없나니"라는 말씀처럼, 구약의 제사는 죄를 근본적으로 해결하지 못했고 사람의 양심까지 온전히 깨끗하게 할 수는 없었다.

이어지는 10절은 이러한 제도가 "개혁할 때까지 맡겨 둔 것"이라고 말한다. 

이는 장차 오실 예수 그리스도를 통해 이루어질 완전한 구원을 예표하는 것이었다. 

결국 예수님께서 십자가에서 흘리신 보혈만이 모든 인류의 죄를 영원히 해결하실 수 있는 유일한 제사였다.

하나님께서는 죄 가운데 있는 인류에게 참된 해방과 자유를 주시기 위해 가장 사랑하시는 독생자 예수 그리스도를 제사의 어린양으로 내어주셨다. 인간의 이성으로는 다 이해할 수 없는 크고 놀라운 사랑이다.

영원한 대제사장이신 예수님의 희생으로 내가 구원을 받았음을 생각할 때, 주님을 사랑하지 않을 수 없다. 

이제는 과거의 지성소가 아니라 주님 안에 거하며 살아가는 것이 성도에게 허락된 가장 큰 복임을 다시 깨닫게 된다. 

오늘도 그 은혜를 기억하며 감사와 사랑으로 주님과 동행하는 삶을 살아가기를 소망한다.

8.인간 찾기(해석)

9. 적용 (구체적으로) 

나의 죄를 온전히 용서하시고 구원하신 나의 영원한 대제사장이신 예수를 찬양합니다. 오늘 시간을 내어 십자가의 사랑을 더욱 묵상해야겠다. 

10. 영적 터치 (단어/구절):

10절: 개혁할 때까지 맡겨 둔 것이니라

11. 믿음과 회개 및 감사 기도로 마무리하기

12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);
INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-10-15', '히브리서', '9장 11~20절', '새 언약의 중보자', '히브리서 9장 11~20절

11   그리스도께서는 장래 좋은 일의 대제사장으로 오사 손으로 짓지 아니한 것 곧 이 창조에 속하지 아니한 더 크고 온전한 장막으로 말미암아

12   염소와 송아지의 피로 하지 아니하고 오직 자기의 피로 영원한 속죄를 이루사 단번에 성소에 들어가셨느니라

13   염소와 황소의 피와 및 암송아지의 재를 부정한 자에게 뿌려 그 육체를 정결하게 하여 거룩하게 하거든

14   하물며 영원하신 성령으로 말미암아 흠 없는 자기를 하나님께 드린 그리스도의 피가 어찌 너희 양심을 죽은 행실에서 깨끗하게 하고 살아 계신 하나님을 섬기게 하지 못하겠느냐

15   이로 말미암아 그는 새 언약의 중보자시니 이는 첫 언약 때에 범한 죄에서 속량하려고 죽으사 부르심을 입은 자로 하여금 영원한 기업의 약속을 얻게 하려 하심이라

16   유언은 유언한 자가 죽어야 되나니

17   유언은 그 사람이 죽은 후에야 유효한즉 유언한 자가 살아 있는 동안에는 효력이 없느니라

18   이러므로 첫 언약도 피 없이 세운 것이 아니니

19   모세가 율법대로 모든 계명을 온 백성에게 말한 후에 송아지와 염소의 피 및 물과 붉은 양털과 우슬초를 취하여 그 두루마리와 온 백성에게 뿌리며

