8.인간 찾기(해석)

- 사라는 89세에 내년 이 맘 때에 아이를 낳을 것이라는 하나님의 말씀을 듣고 비웃었으나, 왜 비웃느냐 꾸짖는 하나님의 말씀을 듣고 확실한 믿음이 생겼다

- 하나님의 능력을 경험한 사라는 자신의 단산함과 상관없이 하나님께서 이루실 것이라는 믿음이 생겼다.

- 믿음은 하나님께서 찾아오셔서 역사하셔야만 생기는 것이다.

- 믿음의 선진들은 약속이 이루어지는 것을 경험하지 못했으나 멀리서 보고 환영했다. 하나님의 약속의 말씀을 확실히 믿은 것이다.

- 오늘날 우리 신자들도 이들은 본받아 복스러운 소망 곧 하나님과 함께 천국에 거하는 그 날을 믿음으로 바라봐야 한다.

- 믿음의 선진들은 이 땅에서 자신은 나그네임을 증언하였는데, 이것은 자신의 시민권이 하나님 나라(본향)에 있음을 믿고 하나님 나라를 찾는 자임을 나타낸 것이다.  

- 아브라함은 ''이삭을 통하여 너의 자손이 하늘의 셀 수 없는 별처럼 많아질 것이다'' 말씀하신 하나님의 약속을 기억하고 믿었다.(창 15장)

- 이삭을 죽은 자 가운데서 다시 살리실 줄로 확실히 믿었기에 이삭을 제물로 드린 것이다.

- 아빠 아브라함의 믿음을 보고 자란 아들 이삭 또한 믿음으로 야곱과 에서를 축복했다.

- 자신을 제물로 바치는 아빠의 믿음과 그 믿음을 보고 자기 대신 어린양을 제물로 드리게 하신 하나님을 경험한 이삭은 이미 그 순간 믿음의 사람이 되었을 것이다.

    

9.적용(나) 

- 믿음의 선진들은 모두 하나님을 만났고 하나님의 말씀에 순종하였다.

- 그 말씀이 바로 이루어지지 않고 수십년 걸리기도 하고 노아의 경우 120년이 걸리기도 하지만, 그들은 하나님의 말씀을 붙들고 묵묵히 살아갔다.

- 찾아와주신 하나님께 감사하며 믿음의 선진들처럼 주신 말씀 부여잡고 묵묵히 살아가는 내가 되길 소망한다.

- 나는 이 땅에서 나그네이며 나 또한 본향을 찾는 자임을 나타내는 삶을 살아야겠다. 

