8. 인간(해석):

- 오늘 히브리서를 묵상하며 두 사람의 믿음이 마음에 깊이 남았다.

- 첫 번째는 요셉의 믿음이다. 우리는 말씀과 예배, 기도를 통해 하나님의 약속을 붙들지만, 시간이 흐를수록 믿음은 쉽게 흔들린다. 대부분은 살아 있는 동안 응답받기를 원하기 때문이다. 그러나 요셉은 달랐다. 그는 하나님께서 약속하신 가나안 땅에 들어가지 못한 채 애굽에서 죽음을 맞이했지만, 자신의 뼈를 반드시 그 땅으로 옮겨 달라고 유언했다. 죽음 이후에도 하나님의 약속은 반드시 이루어진다는 사실을 믿었기 때문이다. 그의 믿음은 후손들에게 소망이 되었고, 결국 400여 년 후 그의 뼈는 가나안 땅에 안장되었다. 하나님의 약속은 사람의 생애보다 크고, 하나님의 시간 속에서 반드시 이루어진다는 사실을 보여 준다.

- 두 번째는 모세의 믿음이다. 모세는 애굽의 부귀와 영화를 뒤로하고 하나님의 백성과 함께 고난받는 길을 선택했다. 말은 쉽지만 실제로 그런 선택을 하기는 어렵다. 그러나 모세는 잠시 누리는 죄악의 즐거움보다 하나님과 함께하는 고난이 더 귀하다는 것을 알았다. 그래서 출애굽의 과정과 광야에서의 수많은 어려움도 믿음으로 감당할 수 있었다.

- 오늘 나는 어떤 믿음으로 살아가고 있는지 돌아본다. 현실의 어려움 때문에 눈앞의 문제만 바라볼 때가 많지만, 하나님께서는 영원한 소망을 바라보는 믿음을 원하신다. 잠시 스쳐 지나갈 세상의 즐거움보다 하나님께서 약속하신 나라를 더욱 사모하며, 끝까지 믿음을 붙드는 삶을 살아가기를 기도한다.

9. 적용(나): 

- 믿음으로 소망을 품고 살아가길 기도해야겠다.

